const mediaSearch=query=>`https://commons.wikimedia.org/w/index.php?search=${encodeURIComponent(query)}&title=Special:MediaSearch&type=image`;
async function commonsImage(query,fallback){
  const get=async q=>{const url=`https://commons.wikimedia.org/w/api.php?action=query&generator=search&gsrnamespace=6&gsrlimit=1&gsrsearch=${encodeURIComponent(q)}&prop=imageinfo&iiprop=url&iiurlwidth=960&format=json&origin=*`;const json=await fetch(url).then(r=>r.json());const page=Object.values(json.query?.pages||{})[0];return page?.imageinfo?.[0];};
  try{return await get(query)||await get(fallback);}catch{return null;}
}
function esc(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function ukDescription(item,city){const kinds={"Sehenswürdigkeit":`${item.title} — конкретна пам’ятка в ${city}; перевірте години роботи перед візитом.`,"Restaurant & Café":`${item.title} — заклад для їжі або кави в ${city}; перевірте меню, години роботи й бронювання.`,"Hidden Spot":`${item.title} — менш відоме місце в районі ${city}; відвідуйте лише легально доступні зони.`,"Erlebnis & Video":`${item.title} — окремий досвід або ідея для відео; заздалегідь перевірте доступність, погоду й вартість.`};return kinds[item.category];}
function items(profile){return Object.entries(profile.groups).flatMap(([category,entries])=>entries.map(entry=>{const item={...entry,category,url:entry.url||map(entry.title,profile.name),imageQuery:entry.imageQuery||`${entry.title} ${profile.name}`};return {...item,ukDescription:ukDescription(item,profile.name)};}));}
function card(profile,item,index){const t=ui[activeLanguage];const category=activeLanguage==='uk'?categoryUa[item.category]:item.category;const description=activeLanguage==='uk'?item.ukDescription:item.description;const placeUrl=item.url||map(item.title,profile.name);return `<article class="place-card" data-category="${esc(item.category)}"><a class="place-image" href="${mediaSearch(item.imageQuery)}" target="_blank" rel="noopener"><img alt="${esc(item.title)} â€“ Wikimedia Commons" loading="lazy" data-query="${esc(item.imageQuery)}" data-fallback="${esc(profile.name)}"><span>${t.image}</span></a><div class="place-body"><div class="place-top"><span class="place-tag">${category}</span><span class="place-number">${String(index+1).padStart(2,'0')}</span></div><h3>${esc(item.title)}</h3><p class="place-description">${esc(description)}</p><details><summary>${t.planning}</summary><p>${activeLanguage==='uk'?'ÐŸÐµÑ€ÐµÐ²Ñ–Ñ€Ñ‚Ðµ Ð³Ð¾Ð´Ð¸Ð½Ð¸ Ñ€Ð¾Ð±Ð¾Ñ‚Ð¸, Ð²Ñ…Ñ–Ð´ Ñ– Ð±Ñ€Ð¾Ð½ÑŽÐ²Ð°Ð½Ð½Ñ Ð·Ð°Ð·Ð´Ð°Ð»ÐµÐ³Ñ–Ð´ÑŒ.':'Ã–ffnungszeiten, Eintritt und Reservierung vorab prÃ¼fen.'}</p></details><a class="place-link" href="${placeUrl}" target="_blank" rel="noopener">${t.website}</a><a class="place-link" href="${profile.guide}" target="_blank" rel="noopener">${t.guide}</a></div></article>`;}
function hydrateImages(root){root.querySelectorAll('img[data-query]').forEach(async img=>{const info=await commonsImage(img.dataset.query,img.dataset.fallback);if(!info?.thumburl)return;img.src=info.thumburl;img.closest('.place-image').href=info.descriptionurl||mediaSearch(img.dataset.query);img.alt=img.dataset.query+' â€“ Bildquelle Wikimedia Commons';});}
