    if(nav.querySelector('.return-submenu'))return;
const markup=`<details class="return-submenu" ${activeReturn||activeTrips?'open':''}><summary>â†©ï¸ RÃ¼ckreise</summary><div class="return-submenu-links"><a class="${activeReturn?'active':''}" href="return.html">âœˆï¸ DirektflÃ¼ge</a><a class="${activeTrips?'active':''}" href="return-trips.html">ðŸšŒ Roadtrip RÃ¼ckreise</a></div></details>`;
